<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Parachute Repair Manual</title>
<style>
  body {
    font-family: "Times New Roman", Times, serif;
    font-size: 15px;
    line-height: 1.5;
    color: #000;
    margin: 0;
    padding: 40px;
    display: flex;
    justify-content: center;
    background-color: #fff;
  }
  .page-container {
    display: flex;
    max-width: 900px;
    width: 100%;
    gap: 40px;
  }
  .column {
    flex: 1;
    display: flex;
    flex-direction: column;
  }
  .placeholder {
    background-color: #e8e8e8;
    border: 1px solid #aaa;
    border-radius: 6px;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #555;
    font-family: sans-serif;
    font-size: 14px;
    margin-bottom: 15px;
    overflow: hidden;
    width: 100%;
    aspect-ratio: 1.4 / 1;
  }
  .circle-label {
    position: absolute;
    top: 12px;
    left: 12px;
    background: radial-gradient(circle at 30% 30%, #ff4d4d, #b30000);
    color: white;
    border-radius: 50%;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-family: sans-serif;
    font-size: 13px;
    box-shadow: 1px 1px 4px rgba(0,0,0,0.6);
  }
  .step-text {
    margin-top: 0;
    margin-bottom: 25px;
    padding-left: 28px;
    text-indent: -28px;
  }
  .step-text em {
    font-style: italic;
  }
  .page-number {
    margin-top: auto;
    font-size: 16px;
    font-family: Arial, sans-serif;
    font-weight: normal;
  }
  h3 {
    font-size: 16px;
    margin-top: 0;
    margin-bottom: 12px;
  }
  .heading-inspection {
    font-style: italic;
    font-weight: bold;
  }
  .heading-repair {
    font-weight: bold;
    margin-top: 25px;
  }
  .heading-procedure {
    font-style: italic;
    font-weight: bold;
    margin-top: 25px;
  }
  .heading-disassembly {
    font-style: italic;
    font-weight: bold;
    margin-top: 25px;
  }
  ul {
    margin-top: 0;
